INSERT INTO `story_details` (`id`,`project_id`,`userstory_id`,`pre_requsite`,`summary`,`actions`,`test_data`,`acceptance_criteria`,`created`,`updated`) VALUES
(623,103,1101,'["User must have a registered and active account in the system", "System database must be operational and accessible for credential verification", "Network connectivity to the authentication server must be available", "User session management services must be configured and running", "Application environment must support HTTPS/TLS for credential transmission"]','Implement user authentication functionality allowing registered users to access their personal accounts through credential-based login.','["User navigates to login page", "User inputs email/username", "User inputs password", "System validates credentials against stored data", "System redirects user to dashboard upon success", "System displays specific error message upon validation failure"]','["username","password","URL"]','["Login form must be visible on the homepage or dedicated login page", "Fields \'email\' and \'password\' must be present and marked as required", "UI must prevent entry until both fields are filled (client-side validation)", "System must verify credentials hash against secure database record", "User must be redirected to \'/dashboard\' route with HTTP 200 status on success", "Appropriate HTTP Security headers must be sent to protect credentials", "If credentials are invalid, an error screen must appear without revealing if username or password was wrong", "If user account is locked/suspended, specific error or disabled login state must be shown", "System must log login attempts for audit purposes (success/login_id)", "Password input field must not store or echo values in browser history or logs"]','2026-04-10 06:53:36','2026-04-10 09:07:03'),
(624,103,1104,'["User is authenticated and authorized to access Purchase Order and Inventory Management modules", "User holds a valid role (e.g., Procurement Admin, Warehouse Manager)", "The relevant Purchase Order exists in the system and is currently in \'Open\' status", "Shipment logistics databases (e.g., Shipping API) are operational and accessible", "Inventory API is active to perform stock count updates upon receipt"]','The system enables authorized users to create an in-transit record for an open purchase order, track shipment logistics, and execute the receiving process to update inventory levels accordingly.','["User navigates to the In-Transit Creation screen", "User queries and selects the relevant Purchase Order by PO Number", "System validates PO status and availability", "User enters shipment logistics details (Container, Vessel, BOL)", "User submits to create the In-Transit record", "User initiates the receiving process for items in transit", "User specifies quantity to receive (Full or Partial)", "User confirms the receive action to finalize transaction"]','["PO Number", "PO Status", "Container ID", "Vessel Name", "Bill of Lading Number", "Item SKU", "Shipped Quantity", "Received Quantity", "User Role Name", "Timestamp"]','["UI allows user to search and select a Purchase Order by PO Number", "System prevents record creation if the selected PO is closed or cancelled", "All logistics fields (Container, Vessel, BOL) are required for saving the In-Transit record", "System generates a unique In-Transit record identification upon creation", "Partial receive option reduces In-Transit quantity and increases Received quantity proportionately", "Full receive option sets the In-Transit quantity to zero", "Inventory system updates stock levels immediately after receive confirmation", "System rejects receipt quantity exceeding the shipped quantity on the record", "UI displays error message if required mandatory fields are missing during submission", "System logs all receive transactions with timestamps and user IDs for audit trails"]','2026-04-23 07:13:18','2026-04-23 07:13:18'),
(625,103,1105,'["User possesses \'Inventory Manager\' or \'Cross-Plante Transfer\' role rights", "ERP System instances for PPUSA and PPMTL must be online and connected", "Intercompany integration APIs and EDI channels must be operational", "Inventory master data and Plant hierarchy must be synchronized", "Cross-org authorization rules must be configured in system settings"]','System functionality to enable inventory transfers between locations and automatically generate corresponding intercompany purchase and sales orders, ensuring real-time quantity, price, and stock consistency across PPUSA and PPMTL plants.','["User authenticates and logs into the Warehouse Management system", "User selects source warehouse location from master data list", "User selects destination warehouse location from list", "User enters inventory items and specifies transfer quantities", "System validates source stock availability against requested Qty", "User confirms and submits the transfer request", "System generates intercompany Purchase Order in PPUSA", "System auto-creates Sales Order in PPMTL counterpart", "System deducts stock from source location inventory", "System adds stock to destination location inventory", "System syncs financial and quantity data via API", "System sends success notification to user dashboard"]','["Source_Warehouse_Code", "Destination_Warehouse_Code", "Item_SKU_List", "Transfer_Quantity", "Unit_of_Measure", "Currency_Code", "User_ID", "Plant_Code_Source", "Plant_Code_Dest", "Exchange_Rate"]','["UI must verify source warehouse is not closed or locked", "System must validate sufficient quantity exists at source location", "Source inventory level must decrease by transfer Qty immediately", "Destination inventory level must increase by transfer Qty after sync", "Purchase Order status in PPUSA must reflect \'Created\' or \'Released\'", "Sales Order status in PPMTL must reflect \'Created\' upon PO generation", "Sync latency for quantity updates must not exceed 3 seconds", "Price recorded on SO must match calculated intercompany transfer price", "System must display error if API connection to PPMTL fails", "Audit logs must capture user ID, timestamp, and item SKUs transferred", "Error message must specify \'Insufficient Stock\' if source Qty < Request", "Notification must trigger on successful transfer completion"]','2026-04-23 10:14:20','2026-04-23 10:14:20'),
(626,103,1106,'["User authentication with Manufacturing and Finance module permissions", "Existence of valid Product Master and Material data", "Availability of active Inventory System and Warehouse locations", "Upstream Order Management System API availability", "Accouting System readiness for Deferred Revenue posting"]','Enables creation of Cutting and Welding BOMs for inventory transformation and integrates financial deferred revenue management for processing financial values and deposit updates within the manufacturing workflow.','["User selects orders eligible for inventory processing", "System generates Cutting BOM for required raw materials", "System generates Welding BOM for component assembly", "New finished inventory items are created and stocked", "System creates Deferred Revenue Invoice for the order", "Deposit status is updated to reflect allocation", "System updates Inventory History records"]','["Order ID", "Material SKU", "Revenue Amount", "Inventory Location Code", "Order Status", "Deposit ID"]','["Cutting BOM is created and visible in the system", "Welding BOM is created and linked to Cutting BOM", "New inventory record is generated with correct quantity", "Inventory history table reflects the new transformation", "Deferred Revenue Invoice is generated in Finance module", "Deposit status changes from Pending to Applied/Reconciled", "Invoice value accurately matches the deferred revenue amount", "Backend validations prevent duplicate BOM creation", "System handles errors for insufficient material quantities"]','2026-04-27 06:00:32','2026-04-27 06:00:32'),
(628,103,1102,'["User account must exist in the database", "User account status must be Active", "HTTPS connection must be available", "Authentication service API must be operational"]','Enable users to authenticate into the application by providing valid credentials and gaining access to user features.','["Navigate to the login page", "Enter username or email address", "Enter password", "Submit the login form", "System validates credentials against backend", "Redirect to dashboard upon success", "Display error message upon invalid credentials"]','["Valid Username", "Valid Password", "Invalid Username", "Invalid Password", "User Status: Locked"]','["Valid credentials result in successful redirection to the home page", "Invalid credentials display a specific error message", "Empty fields prevent form submission with validation hints", "Session ID is generated only after successful authentication", "Failed login attempts are logged in the audit trail", "Password input fields obscure characters", "Account lockout mechanism triggers if failure threshold is reached"]','2026-05-05 04:47:37','2026-05-05 04:47:37'),
(629,103,1108,'["User must have \'Business User\' role or higher access rights", "IMS Application must be deployed and accessible", "Authentication Service and Session Management APIs must be online", "Database storing Orders and Users must be connected", "PDF Generation Service must be available", "Browser environment must support secure cookies and JavaScript"]','Enables authorized business users to authenticate into the IMS application, perform comprehensive order management tasks including search, creation, approval, and cancellation, and securely terminate sessions via automated PDF reporting capabilities.','["Enter username and password for authentication", "Navigate to order management dashboard successfully", "Apply filters to search orders by ID, Customer Name, ID, Project, Deposit, and 999 Price", "Create new order with quantity, pricing, and customer details", "Save order draft and submit for approval workflow", "Approve orders after verifying pricing and quantity updates", "Cancel orders if no shipping record exists within shipping system", "Generate Order Status PDF for specific orders", "Generate Order Acknowledgement PDF with accurate data", "Initiate secure logout to clear session and return to login screen"]','["Valid Username", "Valid Password", "Invalid Username", "Invalid Password", "Order ID", "Customer Name", "Customer ID", "Project Name", "Deposit Amount", "999 Price", "Order Quantity", "Order Pricing Details", "Shipping Record Presence", "Order Status Type", "PDF Generation Service URL", "Session ID"]','["System displays validation error message and blocks access when username or password is invalid", "Successful logout clears the session and redirects the user back to the login page immediately", "User can filter order search results using Order ID, Customer Name, Customer ID, Project Name, Deposit, and 999 Price criteria", "Authorized users can create orders, and system must validate quantity/pricing before saving", "Order status must transition correctly from Created to Saved to Approved with price updates", "System prevents cancellation of an order if a shipping record exists in the downstream system", "Order status must update to Cancelled only after successful cancellation with no shipping record", "Generated Order Status and Order Acknowledgement PDFs must contain complete text and accurate numeric data", "UI displays error message for field-level validation failures before submission", "System must validate that the requesting user has permission to create or approve orders before allowing the action", "PDF generation request must timeout or fail gracefully if the backend service is unreachable"]','2026-05-18 09:52:46','2026-05-18 09:52:46'),
(630,103,1109,'["User account must be registered in the IMS system database", "Valid authentication credentials (username and password) must be configured", "User role must include \'Order Management\' or equivalent permissions", "IMS Application server must be operational and accessible", "Session management API must be active for login/logout", "Order database must be initialized with schema for order tracking", "Shipping record API or logic must be available to validate cancellation"]','Enables business users to securely authenticate into the IMS application, perform end-to-end order management including search, creation, approval, cancellation, and PDF generation, and properly manage session security via logout.','["User submits login credentials for authentication", "System validates credentials and grants dashboard access", "User views order dashboard and applies specific filters", "User searches orders using order details and numeric ranges", "User creates new order entries with quantity and pricing", "User saves order as draft or approves for final processing", "User cancels orders where shipping records do not exist", "System updates order status and inventory or state fields", "User generates and downloads PDF order documentation", "User logs out to terminate the active session"]','["Username", "Password", "Customer Name", "Customer ID", "Order ID", "Project Name", "Deposit Amount", "999 Price", "Order Quantity", "Shipping Record Status", "Order Status", "User Role", "Order Description", "Unit Price", "Total Amount"]','["AC1 \\u2013 System displays validation message upon invalid username or password and blocks login", "AC2 \\u2013 User must be able to logout successfully, session clears, and redirect to login page is functional", "AC3 \\u2013 Order search must return accurate results based on Order ID, Customer Name, ID, Project, Deposit, and 999 Price filters", "AC4 \\u2013 Authorized users must successfully create, save (Draft), and approve orders with status updates and data validation", "AC5 \\u2013 Order cancellation must be restricted to Created/Approved orders without shipping records and status must update to Cancelled", "AC6 \\u2013 Generated Order Status and Acknowledgement PDFs must contain accurate and complete order data", "UI should display error messages clearly for failed actions like duplicate order entry", "System must log all order state changes including creation, approval, and cancellation events", "PDF generation must handle large order volumes without timeout or memory errors", "Logout must invalidate session tokens across all open tabs of the application"]','2026-05-22 11:55:31','2026-05-22 11:55:31'),
(631,103,1103,'["User must be authenticated or have access to the registration/login form", "Web browser with JavaScript enabled must be configured", "System API endpoints for account creation/update must be available", "Staging or Pre-Production environment status must be active"]','System must validate password field inputs against defined security policies (complexity, length) on the client and server side before allowing form submission.','["Navigate to the account registration or password change page", "Enter a text string into the password input field", "Click the submit or save button on the form", "Verify UI feedback messages appear on the screen", "Check backend processing logs for validation errors"]','["username", "email", "password", "confirmPassword"]','["UI displays \'Password is required\' error message when field is empty and submit is triggered", "UI displays specific error message when password length is less than minimum requirement (e.g., < 8 characters)", "UI displays error message when password fails complexity rules (e.g., missing number or special character)", "System successfully saves the account only when password meets all defined validation criteria", "Backend API returns a 400 Bad Request status code with a validation error body when password fails checks", "UI validation messages are displayed inline within the field boundary or at the top of the form immediately upon submit attempt"]','2026-05-22 12:21:54','2026-05-22 12:21:54'),
(632,103,1110,'["User must possess \'Manufacturing Engineer\' or \'Account Manager\' role access", "Valid existing Sales Order or Material Purchase Request record in ERP", "Material Master Data must be populated with cutting/welding specs", "Integration between Inventory and Finance (Accounting) modules must be active", "System environment must be configured for UAT or Production", "Customer master data must be synced with billing module"]','Allows users to generate Cutting and Welding BOMs to transform raw materials and simultaneously process deferred revenue invoicing to maintain accurate financial records.','["User defines raw material selection and cutting specifications", "User inputs welding configuration details for the product", "System calculates transformation quantities and generates new BOMs", "System updates inventory records for consumed raw materials", "System creates stock records for finished goods", "System calculates deferred revenue amount based on order value", "System generates invoice and updates deposit status", "System updates inventory history ledger with transaction details"]','["Material_SKU_ID", "Order_ID", "Raw_Material_Quantity", "Finished_Good_Quantity", "Unit_Price", "Revenue_Percentage", "Deposit_Amount", "Warehouse_ID", "Invoice_Number_Prefix", "User_Credentials"]','["Cutting BOM record is successfully created in the database with correct schema", "Welding BOM record is successfully created in the database with correct schema", "Finished good inventory quantity is incremented immediately after generation", "Raw material inventory quantity is decremented after consumption", "Inventory History table contains new entry with timestamp and user details", "Deferred Revenue Invoice record is created with accurate financial values", "Order Deposit status changes from \'Pending\' to \'Processed\' or \'Partial\'", "Invoice UI displays total amount, tax, and deferred revenue breakdown correctly", "System validation fails if upstream Order or Material data is missing", "Role-based access control prevents unauthorized modification of financial records"]','2026-05-22 13:15:43','2026-05-22 13:15:43'),
(633,103,1111,'["User authenticated with Manufacturing or Financial Management roles", "Inventory Management Module must be active and accessible", "Sales Order System connectivity must be available for revenue processing", "Product Master Data and Material Ledger must be populated", "Cutting and Welding Station Configuration Data must be defined"]','System functionality to generate specific BOMs for manufacturing processes (cutting/welding) and manage associated financial deferrals within the inventory transformation workflow.','["Select transformation process type (cutting or welding)", "Define input materials and output quantities", "Execute BOM generation logic for transformed goods", "Update inventory ledger for new inventory items", "Record transformation event in inventory history", "Calculate revenue recognition amounts for deferred billing", "Generate deferred revenue invoices based on order status", "Update deposit status and order financial records"]','["Product SKU", "Material Quantity", "Customer ID", "Order Reference ID", "Revenue Amount", "Deposit Value", "Transformation Cost"]','["BOM is created successfully without system errors", "Cutting and Welding BOM documents reflect correct quantities", "Inventory stock levels update to reflect net transformation results", "Inventory history log captures timestamp and material source/destination", "Deferred revenue invoice is generated and linked to the correct order", "Deposit status field updates accurately to current payment state", "Invoice totals calculate accurately against financial rules", "System validates sufficient raw material stock before processing", "UI displays financial breakdown clearly upon transaction completion"]','2026-05-25 06:21:01','2026-05-25 06:21:01'),
(645,103,1124,'["User must be authenticated (role: Inventory or Finance)", "Material master data must be available in system", "Inventory transaction system is accessible", "Financial transaction system is operational", "Database connection is established"]','Create cutting and welding BOM for inventory transformation and generate deferred revenue invoices for orders.','["Create BOM for cutting and welding materials", "Calculate and generate deferred revenue invoice", "Update inventory with new stock and deposit status", "Record activity in inventory and financial history"]','["material_type", "material_quantity", "order_ref_id", "customer_id", "deferred_amount", "deposit_timestamp"]','["Cutting BOM is created and stored in the system.", "Welding BOM is created and stored in the system.", "Inventory quantity is updated to reflect material transformation.", "New inventory record is generated.", "Inventory history is updated with timestamp and transaction details.", "Deferred revenue invoice is generated with correct amounts.", "Deposit status in the order is updated to reflect payment.", "Invoice reflects correct financial values at time of generation.", "User interface displays creation of BOMs and updates inventory without error.", "System validates that material quantity and order reference are valid.", "Deposits are recorded only when reverse flow of payment exists."]','2026-06-30 10:45:25','2026-06-30 10:45:25'),
(646,103,1126,'["User is authenticated in the system", "Valid login credentials entered", "System authentication enabled", "Upstream authentication service reachable"]','Business user can log into IMS, manage/search orders, create/cancel orders, generate PDFs, and log out securely.','["Login", "Search and filter orders", "Create and approve order", "Cancel order", "Generate order PDF", "Logout"]','["Username", "Password", "Order ID", "Customer Name", "Customer ID", "Project Name", "Deposit", "999 Price", "Quantity", "Price"]','["AC1 \\u2013 Login Validation: System displays validation message for invalid username or password and prevents login access.", "AC2 \\u2013 Logout: User logs out successfully and redirects to login page where they can log in again with valid credentials.", "AC3 \\u2013 Order Search and Filters: User can search and filter orders using Order ID, Customer Name, Customer ID, Project Name, Deposit, and 999 Price filters.", "AC4 \\u2013 Order Creation and Approval: Authorized users can create, save, and approve orders with updated quantity and pricing details; order status updates correctly.", "AC5 \\u2013 Order Cancellation: User can cancel created or approved orders when no shipping record exists; order status updates to Cancelled.", "AC6 \\u2013 Order PDF: System generates accurate Order Status and Order Acknowledgement PDFs containing complete order information.", "Missing Criteria: User must be authenticated before performing any order-related action; system must validate order cancellation only if shipping record is absent and backend updates status accordingly."]','2026-06-30 10:50:06','2026-06-30 10:50:06'),
(647,103,1127,'["Valid login credentials", "Authenticated user session", "Order service operational", "PDF service operational", "System access permissions"]','User can login, search, manage, create/cancel orders, generate PDFs, and logout for end-to-end order processing.','["Login using valid credentials", "Search and filter orders", "Create, save, and approve order with updated details", "Cancel order when no shipping record exists", "Generate order PDF", "Securely logout redirecting to login page"]','["username", "password", "order_id", "customer_name", "customer_id", "project_name", "deposit", "price", "quantity", "pricing", "order_status"]','["Login fails with validation message for invalid credentials and access denied.", "Logout redirects to login page and clears session.", "Order search filters by Order ID, Customer Name, Customer ID, Project Name, Deposit, and 999 Price.", "Authorized users can create, save, and approve orders; quantity and price updates are saved and order status changes accordingly.", "Cancel created or approved orders only if no shipping record exists; status updates to Cancelled.", "System generates accurate Order Status and Order Acknowledgement PDFs containing complete order information.", "All inputs undergo validation; errors are reported to user."]','2026-06-30 10:57:55','2026-06-30 10:57:55'),
(649,103,1129,'["Valid username and password provided", "User is authorized for order processes", "Login and order management services are available", "Session exists for reusable state"]','Log into the IMS application, perform order search, create or approve orders, cancel orders, generate order PDFs, and log out to complete end-to-end order processing.','["Login", "Search and filter orders", "Create or approve orders", "Cancel orders", "Generate order PDFs", "Log out"]','["username", "password", "Order ID", "Customer Name", "Customer ID", "Project Name", "Deposit", "999 Price", "Action:Create", "Action:Approve", "Action:Cancel"]','["AC1: System displays validation message for invalid credentials and prevents login access", "AC2: User logs out, is redirected to login page, and can log in again with valid credentials", "AC3: User can search and filter orders using Order ID, Customer Name, Customer ID, Project Name, Deposit, and 999 Price", "AC4: Authorized users can create, save, and approve orders with updated quantity and pricing; order status updates correctly", "AC5: User can cancel Created or Approved orders only if no shipping record exists; status updates to Cancelled", "AC6: System generates Order Status and Order Acknowledgement PDFs containing complete accurate order information", "Additional: After any order creation, approval, or cancellation, the system reports status change; PDFs are generated only after order data is valid"]','2026-07-06 06:29:52','2026-07-06 06:29:52'),
(650,103,1130,'["User has valid credentials (username and password) to authenticate.", "User is authorized role: Order Manager with permissions to view, create, edit, cancel orders and generate PDFs.", "System is reachable and the IMS application instance is operational."]','Business users can authenticate, search, manage, modify, and cancel orders, generate order PDFs, and securely log out within the IMS system.','["Login with username and password", "Search orders using Order ID, Customer Name, Customer ID, Project Name, Deposit, or 999 Price", "View order details and status", "Create a new order with quantity and pricing and approve it", "Cancel an approved order (if no shipping record exists) changing status to Cancelled", "Generate Order Status and Order Acknowledgement PDFs", "Logout securely returning to login page"]','["Username", "Password", "Order ID", "Customer Name", "Customer ID", "Project Name", "Deposit", "999 Price", "Order Status", "Cancellation Decision"]','["AC1 \\u2013 Login Validation: System displays a validation message when an invalid username or password is entered and prevents login access.", "AC2 \\u2013 Logout Functionality: User logs out successfully and is redirected to the login page where they can log in again using valid credentials.", "AC3 \\u2013 Order Search and Filters: User can search and filter orders using filters for Order ID, Customer Name, Customer ID, Project Name, Deposit, and 999 Price, with results returned promptly.", "AC4 \\u2013 Order Creation and Approval: Authorized users create, save, and approve orders with updated quantity and pricing details, and the order status updates to Approved.", "AC5 \\u2013 Order Cancellation: Order can only be cancelled when it is either Created or Approved and no shipping record exists, changing the status to Cancelled without affecting downstream processes.", "AC6 \\u2013 Order PDF Validation: System generates Order Status and Order Acknowledgement PDFs that contain all complete and accurate order information, including generated fields and calculated values.", "AC7 \\u2013 Business Validation: Cancellation is blocked if a shipping record exists for the order, and duplicate order entries are prevented during creation."]','2026-07-06 06:38:23','2026-07-06 06:38:23'),
(651,103,1131,'["Business user possesses valid login credentials", "System authentication is configured and accessible", "IMS backend services (order management, PDF generation) are operational and reachable", "User interface loaded and responsive"]','Log in and perform end-to-end order processing including search, creation, cancellation, PDF generation, and secure logout.','["Login with credentials", "Search and filter orders using order details", "Create and approve order with quantity and price updates", "Cancel order if no shipping record (status \\u2192 Cancelled)", "Generate Order Status and Acknowledgement PDFs", "Securely log out"]','["username", "password", "order_id", "customer_name", "customer_id", "project_name", "deposit", "price"]','["System displays validation message for invalid login and blocks access", "Logout redirects to login page and restores ability to authenticate with valid credentials", "Order search returns filtered list supporting filters: Order ID, Customer Name, Customer ID, Project Name, Deposit, 999 Price", "Order creation allows saving and approval, updates quantity and pricing, and changes order status", "Approved order status updates accordingly", "Cancellation allowed only when no shipping record exists, resulting in Cancelled status", "Generated PDFs contain complete, accurate order data with correct formatting, PDF generation is triggered only for valid order", "All input fields perform required validations (e.g., numeric order ID, valid numeric deposit/price)", "UI reflects current order status and logout state"]','2026-07-06 07:56:48','2026-07-06 07:56:48'),
(652,103,1133,'["Valid user account with username and password", "User authorized role to perform order operations", "IMS authentication service available", "Order management backend API operational", "User interface accessible"]','A business user can log into the IMS, search and filter orders, create and approve orders with quantity and pricing updates, cancel orders without shipping, generate PDFs, and securely log out.','["Login with valid credentials", "Search and filter orders using order details filters", "Create order with updated quantity and pricing and submit for approval", "Cancel order (no shipping record) and update status", "Generate order Status and Order Acknowledgement PDFs", "Logout and return to login page"]','["username", "password", "order_id", "customer_name", "customer_id", "project_name", "deposit", "price_999"]','["AC1: Invalid login credentials display validation message and block login access.", "AC2: Successful logout redirects to login page and allows re-login with valid credentials.", "AC3: User can search/filter orders using filters for Order ID, Customer Name, Customer ID, Project Name, Deposit, and 999 Price.", "AC4: Authorized users can create, save, and approve orders with quantity and pricing updates, and status reflects approval.", "AC5: User can cancel created or approved orders only when no shipping record exists, updating status to Cancelled.", "AC6: System generates Order Status and Order Acknowledgement PDFs containing complete accurate order information.", "Missing login failure: system returns error and shows validation UI for invalid credentials.", "Missing PDF generation failure: system does not generate PDF for non-existent orders."]','2026-07-31 16:11:01','2026-07-31 16:11:01'),
(653,103,1132,'["Valid login credentials (username & password) provided", "User is an authorized business user role (e.g., order manager)", "Authentication service available", "Backend order database accessible", "PDF generation service available", "Secure logout mechanism enabled"]','Business users can login, view/search orders, create and approve orders, cancel orders, generate order PDFs, and securely logout.','["Log in with credentials to IMS application", "Search and filter orders using order details", "Create, save, and approve an order with quantity and pricing", "Cancel an approved order (no shipping record) and update status to Cancelled", "Generate Order Status PDF and Order Acknowledgement PDF", "Log out securely and return to login page"]','["Username", "Password", "Order ID", "Customer Name", "Customer ID", "Project Name", "Deposit", "Price", "Quantity", "Pricing"]','["Validation message displayed when invalid login credentials entered, preventing login.", "User can log out successfully and be redirected to login page, allowed to log in again with valid credentials.", "User can search and filter orders using Order ID, Customer Name, Customer ID, Project Name, Deposit, and 999 Price via the search UI.", "Authorized users can create, save, and approve orders with updated quantity and pricing; the order status updates correctly accordingly.", "Users can cancel orders only when no shipping record exists; the order status updates to Cancelled.", "System generates Order Status PDF and Order Acknowledgement PDF containing complete and accurate order information on demand.", "Role-based access control ensures only authorized users perform create, approve, cancel, logout, and login actions.", "System enforces business rule that pending approval orders cannot be cancelled until status changes to Approved."]','2026-07-31 16:11:06','2026-07-31 16:11:06'),
(654,103,1134,'["Valid user credentials provided", "IMS application accessible and responsive", "Order database query capability available", "PDF generation service reachable"]','Business user can perform end-to-end order processing within the IMS application: login, search/filter/manage orders, create/approve/cancel orders, generate order PDFs, and securely log out.','["Log in with valid credentials", "Search and filter orders using available filters", "Create, save, and approve orders", "Cancel orders without shipping record", "Generate and download order PDF", "Log out successfully to login page"]','["username", "password", "order_id", "customer_name", "customer_id", "project_name", "deposit", "price"]','["When an invalid username or password is entered, the system displays a validation message and prevents login (AC1)", "Successful logout redirects the user to the login page, where they can log in again with valid credentials (AC2)", "The user can search and filter orders using order details: Order ID, Customer Name, Customer ID, Project Name, Deposit, and Price (AC3)", "Authorized users can create, save, approve orders, and the corresponding order status updates correctly (AC4)", "Users can cancel created or approved orders only when no shipping record exists, and the status changes to Cancelled (AC5)", "The system generates Order Status and Order Acknowledgement PDFs containing complete and accurate order information (AC6)", "Order status updates reflect backend changes accurately across all operations.", "The search/filter functionality correctly applies all specified criteria"]','2026-07-31 16:12:38','2026-07-31 16:12:38');
